using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using FileCompass.Updating;
namespace FileCompass {
 internal static class ApplicationUpdatesTests {
  static object Release(string version,string channel,string build,bool draft=false,string digest=null,string url=null){string tag=ApplicationUpdates.Tag(version,channel,build);return new{tag_name=tag,draft=draft,prerelease=channel!="",body="fixture",assets=new[]{new{name=ApplicationUpdates.AssetName,size=1024,digest=digest??"sha256:"+new string('a',64),browser_download_url=url??"https://github.com/"+ApplicationUpdates.Repository+"/releases/download/"+tag+"/"+ApplicationUpdates.AssetName}}};}
  static void Compile(string source,string output,string information,string body){File.WriteAllText(source,"using System;using System.IO;using System.Threading;using System.Reflection;[assembly:AssemblyInformationalVersion(\""+information+"\")][assembly:AssemblyFileVersion(\"99.0.0.1\")]class Fixture{static void Main(){"+body+"}}",new UTF8Encoding(false));string csc=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Microsoft.NET","Framework64","v4.0.30319","csc.exe");using(var process=Process.Start(new ProcessStartInfo(csc,"/nologo /target:winexe /platform:x64 /out:"+SshTerminal.QuoteWindowsArgument(output)+" "+SshTerminal.QuoteWindowsArgument(source)){UseShellExecute=false,CreateNoWindow=true})){if(!process.WaitForExit(20000)||process.ExitCode!=0)throw new Exception("Fixture compilation failed.");}}
  static ReleaseManifest Manifest(string package){var manifest=new ReleaseManifest{Version="99.0.0",Channel="beta",Build="20991231.100"};foreach(var file in Directory.GetFiles(package,"*",SearchOption.AllDirectories)){string relative=file.Substring(package.Length+1).Replace('\\','/');if(relative==UpdateContract.ManifestName)continue;manifest.Files.Add(new ReleaseFile{Relative=relative,Hash=UpdateContract.Hash(file),Size=new FileInfo(file).Length});}UpdateContract.Write(Path.Combine(package,UpdateContract.ManifestName),manifest);return manifest;}
  static VendorUpdate Package(string zip,ReleaseManifest manifest){return new VendorUpdate{Id="app",Name="File Compass",Version=manifest.Version,Channel=manifest.Channel,Build=manifest.Build,Hash=UpdateContract.Hash(zip),Size=new FileInfo(zip).Length,FileName=ApplicationUpdates.AssetName,Source=ApplicationUpdates.Home,Url="https://github.com/"+ApplicationUpdates.Repository+"/releases/download/"+ApplicationUpdates.Tag(manifest.Version,manifest.Channel,manifest.Build)+"/"+ApplicationUpdates.AssetName};}
  static InstallRequest Request(string target,string package,ReleaseManifest manifest){return new InstallRequest{Target=target,Package=package,Release=manifest,OriginalHash=UpdateContract.Hash(Path.Combine(target,UpdateContract.Executable)),ManifestHash=UpdateContract.Hash(Path.Combine(package,UpdateContract.ManifestName))};}
  static string Worker(string job,InstallRequest request){Directory.CreateDirectory(job);string worker=Path.Combine(job,"worker.exe");using(var input=typeof(ApplicationUpdates).Assembly.GetManifestResourceStream("FileCompass.UpdateWorker.exe"))using(var output=File.Create(worker))input.CopyTo(output);string path=Path.Combine(job,"request.json");UpdateContract.Write(path,request);return path;}
  static Process StartWorker(string path){return Process.Start(new ProcessStartInfo(Path.Combine(Path.GetDirectoryName(path),"worker.exe"),SshTerminal.QuoteWindowsArgument(path)+" "+UpdateContract.Hash(path)){UseShellExecute=false,CreateNoWindow=true});}
  internal static int VerifyPackage(string zip,string root){Directory.CreateDirectory(root);try{ReleaseManifest manifest;using(var archive=ZipFile.OpenRead(zip))using(var reader=new StreamReader(archive.GetEntry(UpdateContract.ManifestName).Open()))manifest=new JavaScriptSerializer{MaxJsonLength=8*1048576}.Deserialize<ReleaseManifest>(reader.ReadToEnd());ApplicationUpdates.Stage(Package(zip,manifest),zip,Path.Combine(root,"verified"),CancellationToken.None);File.WriteAllText(Path.Combine(root,"result.txt"),"PASS: production ZIP hash, inventory, x64 executable and identity verified: "+UpdateContract.Information(manifest)+"; "+manifest.Files.Count+" files");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL: "+ex);return 1;}}
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);log.Add(label);File.WriteAllLines(Path.Combine(root,"result.txt"),log);};Action<Action,string> rejects=(run,label)=>{bool rejected=false;try{run();}catch(IOException){rejected=true;}check(rejected,label);};
   try{
    var json=new JavaScriptSerializer();check(UpdateContract.Compare("1.0.0","","20261104.100","1.0.0","","20261104.99")>0,"build counters compare numerically, including 99 to 100");check(UpdateContract.Compare("1.0.1","","20260101.01","1.0.0","","20261104.99")>0,"semantic version takes precedence over the build date");check(UpdateContract.Compare("1.0.0","","20260101.01","1.0.0","beta","20261104.99")>0,"stable release supersedes a beta of the same version");
    var beta=Release("99.0.0","beta","20991231.100");var stable=Release("98.0.0","","20991231.01");var selected=ApplicationUpdates.Parse(json.Serialize(new[]{stable,beta}),"beta");check(selected.Version=="99.0.0"&&ApplicationUpdates.ValidOrigin(selected),"beta channel selects the newest supported GitHub release and exact ZIP URL");check(ApplicationUpdates.Parse(json.Serialize(new[]{stable,beta}),"").Version=="98.0.0","stable installations exclude prereleases");check(ApplicationUpdates.Parse("[]","").Version==null,"repository with no releases is reported without inventing a version");check(ApplicationUpdates.Parse(json.Serialize(new[]{Release("100.0.0","beta","20991231.01",true),beta}),"beta").Version=="99.0.0","draft releases are ignored");
    var missing=ApplicationUpdates.Parse(json.Serialize(new[]{Release("99.0.0","beta","20991231.100",digest:"missing")}),"beta");check(!String.IsNullOrEmpty(missing.Error)&&missing.Hash==null,"missing SHA-256 disables application download");var outside=ApplicationUpdates.Parse(json.Serialize(new[]{Release("99.0.0","beta","20991231.100",url:"https://github.com/attacker/repo/releases/download/fake/file.zip")}),"beta");check(!ApplicationUpdates.ValidOrigin(outside)&&!String.IsNullOrEmpty(outside.Error),"application releases cannot select an asset from another repository");
    var same=new VendorUpdate{Version=BuildInfo.Version,Channel=ApplicationUpdates.CurrentChannel,Build=BuildInfo.Build};check(!ApplicationUpdates.IsNewer(same),"same version and build is not offered as an update");same.Build="20000101.01";check(!ApplicationUpdates.IsNewer(same),"older builds are not offered as updates");same.Build="20991231.999";check(ApplicationUpdates.IsNewer(same),"newer build of the same version is offered");
    string package=Path.Combine(root,"package"),target=Path.Combine(root,"installed");Directory.CreateDirectory(Path.Combine(package,"libraries"));Directory.CreateDirectory(Path.Combine(target,"libraries"));Directory.CreateDirectory(Path.Combine(target,"config"));Directory.CreateDirectory(Path.Combine(target,"data"));File.WriteAllText(Path.Combine(target,"config","user.txt"),"personal settings");File.WriteAllText(Path.Combine(target,"data","user.txt"),"personal data");File.WriteAllText(Path.Combine(target,"development-profile.txt"),"keep profile location");File.WriteAllText(Path.Combine(target,"libraries","sample.dll"),"old library");File.WriteAllText(Path.Combine(package,"libraries","sample.dll"),"new library");
    Compile(Path.Combine(root,"old.cs"),Path.Combine(target,UpdateContract.Executable),"98.0.0-beta+20991231.01","File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,\"old-running.txt\"),\"running\");Thread.Sleep(1800);");Compile(Path.Combine(root,"new.cs"),Path.Combine(package,UpdateContract.Executable),"99.0.0-beta+20991231.100","File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,\"restarted.txt\"),\"new build started\");");var manifest=Manifest(package);string zip=Path.Combine(root,"release.zip");ZipFile.CreateFromDirectory(package,zip);var item=Package(zip,manifest);string staged=Path.Combine(root,"staged");ApplicationUpdates.Stage(item,zip,staged,CancellationToken.None);check(File.Exists(Path.Combine(staged,UpdateContract.Executable)),"downloaded package verifies its SHA-256, file inventory and executable version/build before staging");
    var badHash=Package(zip,manifest);badHash.Hash=new string('0',64);rejects(()=>ApplicationUpdates.Stage(badHash,zip,Path.Combine(root,"bad-hash"),CancellationToken.None),"mismatched ZIP SHA-256 is rejected");var badBuild=Package(zip,manifest);badBuild.Build="20991231.101";badBuild.Url="https://github.com/"+ApplicationUpdates.Repository+"/releases/download/"+ApplicationUpdates.Tag(badBuild.Version,badBuild.Channel,badBuild.Build)+"/"+ApplicationUpdates.AssetName;rejects(()=>ApplicationUpdates.Stage(badBuild,zip,Path.Combine(root,"bad-build"),CancellationToken.None),"release tag and executable build must agree");
    string malicious=Path.Combine(root,"profile.zip");File.Copy(zip,malicious);using(var archive=ZipFile.Open(malicious,ZipArchiveMode.Update))using(var writer=new StreamWriter(archive.CreateEntry("config/user.txt").Open()))writer.Write("overwrite");rejects(()=>ApplicationUpdates.Stage(Package(malicious,manifest),malicious,Path.Combine(root,"bad-profile"),CancellationToken.None),"ZIP cannot overwrite user configuration");
    string traversal=Path.Combine(root,"traversal.zip");File.Copy(zip,traversal);using(var archive=ZipFile.Open(traversal,ZipArchiveMode.Update))using(var writer=new StreamWriter(archive.CreateEntry("libraries/../../escaped.dll").Open()))writer.Write("escape");rejects(()=>ApplicationUpdates.Stage(Package(traversal,manifest),traversal,Path.Combine(root,"bad-traversal"),CancellationToken.None),"ZIP traversal paths are rejected before extraction");
    string extra=Path.Combine(root,"extra.zip");File.Copy(zip,extra);using(var archive=ZipFile.Open(extra,ZipArchiveMode.Update))using(var writer=new StreamWriter(archive.CreateEntry("libraries/unlisted.dll").Open()))writer.Write("unlisted");rejects(()=>ApplicationUpdates.Stage(Package(extra,manifest),extra,Path.Combine(root,"bad-extra"),CancellationToken.None),"unlisted executable payloads are rejected");
    string oldHash=UpdateContract.Hash(Path.Combine(target,UpdateContract.Executable)),job=Path.Combine(root,"rollback");Directory.CreateDirectory(job);var request=Request(target,staged,manifest);rejects(()=>UpdateWorker.Install(request,job,count=>{if(count==2)throw new IOException("Simulated replacement failure");}),"replacement failure triggers rollback");check(UpdateContract.Hash(Path.Combine(target,UpdateContract.Executable))==oldHash&&File.ReadAllText(Path.Combine(target,"libraries","sample.dll"))=="old library","rollback restores all changed installed files");
    job=Path.Combine(root,"cancelled");using(var current=Process.GetCurrentProcess()){request=Request(target,staged,manifest);request.ParentId=current.Id;request.ParentStarted=current.StartTime.ToUniversalTime().Ticks;}string path=Worker(job,request);File.WriteAllText(Path.Combine(job,"cancel.signal"),"cancelled");using(var worker=StartWorker(path)){check(worker.WaitForExit(10000)&&worker.ExitCode==0&&UpdateContract.Hash(Path.Combine(target,UpdateContract.Executable))==oldHash,"cancelled application close does not replace any files");}
    job=Path.Combine(root,"handoff");using(var parent=Process.Start(new ProcessStartInfo(Path.Combine(target,UpdateContract.Executable)){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=target})){
     request=Request(target,staged,manifest);request.ParentId=parent.Id;request.ParentStarted=parent.StartTime.ToUniversalTime().Ticks;path=Worker(job,request);File.WriteAllText(Path.Combine(job,"start.signal"),"authorized close");using(var worker=StartWorker(path)){Thread.Sleep(250);check(!worker.HasExited&&UpdateContract.Hash(Path.Combine(target,UpdateContract.Executable))==oldHash,"external updater waits for the running application to exit");check(worker.WaitForExit(20000)&&worker.ExitCode==0,"external updater replaces files after process exit");}
    }
    for(int i=0;i<50&&!File.Exists(Path.Combine(target,"restarted.txt"));i++)Thread.Sleep(100);check(File.Exists(Path.Combine(target,"restarted.txt"))&&UpdateContract.Hash(Path.Combine(target,UpdateContract.Executable))==manifest.Files.Single(x=>x.Relative==UpdateContract.Executable).Hash,"new application build is automatically relaunched from the installation folder");check(File.ReadAllText(Path.Combine(target,"config","user.txt"))=="personal settings"&&File.ReadAllText(Path.Combine(target,"data","user.txt"))=="personal data"&&File.Exists(Path.Combine(target,"development-profile.txt")),"application update preserves settings, user data and the development profile marker");
    UpdateWorker.Recover(request,job);check(UpdateContract.Hash(Path.Combine(target,UpdateContract.Executable))==oldHash&&File.ReadAllText(Path.Combine(target,"libraries","sample.dll"))=="old library","persistent journal and verified backups can restore a completed or interrupted installation");
    File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count+" checks"}));return 0;
   }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}
  }
 }
}
